steps.instructions:
1. Install ESLint and plugins:
   pnpm --filter @agentkeeper/desktop add -D eslint @eslint/js typescript-eslint eslint-plugin-vue @intlify/eslint-plugin-vue-i18n

2. Create apps/desktop/eslint.config.ts using flat config:
```ts
import pluginVue from 'eslint-plugin-vue'
import vueI18n from '@intlify/eslint-plugin-vue-i18n'
import tseslint from 'typescript-eslint'

export default tseslint.config(
  ...pluginVue.configs['flat/recommended'],
  {
    plugins: { '@intlify/vue-i18n': vueI18n },
    rules: {
      '@intlify/vue-i18n/no-raw-text': ['error', {
        ignoreNodes: ['pre', 'code', 'script'],
        ignorePattern: '^[\\s\\d\\W]+$',
        ignoreText: ['|', '/', '–', '…']
      }],
      '@intlify/vue-i18n/no-missing-keys': 'error'
    },
    settings: {
      'vue-i18n': {
        localeDir: './src/renderer/src/locales/*.json',
        messageSyntaxVersion: '^9.0.0'
      }
    }
  },
  { ignores: ['src/renderer/src/components/ui/**'] }
)
```

3. Add lint script to apps/desktop/package.json:
   "lint": "eslint src/renderer/src --ext .vue,.ts"

4. Run `pnpm --filter @agentkeeper/desktop lint` — must exit 0 with zero errors. If any no-raw-text violations remain (strings missed in step 3), add them to en.json and convert them now.

5. Add lint to root package.json scripts:
   "lint": "pnpm --filter @agentkeeper/desktop lint"

1. Install vitest if not present in apps/desktop/:
   pnpm --filter @agentkeeper/desktop add -D vitest

2. Create apps/desktop/vitest.config.ts:
```ts
import { defineConfig } from 'vitest/config'
export default defineConfig({
  test: {
    environment: 'node',
    include: ['src/**/*.test.ts']
  }
})
```

3. Create apps/desktop/src/renderer/src/locales/locale-parity.test.ts:
```ts
import { describe, it, expect } from 'vitest'
import { readdirSync, readFileSync } from 'node:fs'
import { resolve, join } from 'node:path'

const LOCALES_DIR = resolve(__dirname)
const files = readdirSync(LOCALES_DIR).filter(f => f.endsWith('.json'))
const locales = Object.fromEntries(
  files.map(f => [f, Object.keys(JSON.parse(readFileSync(join(LOCALES_DIR, f), 'utf-8'))).sort()])
)
const baseKeys = locales['en.json']

describe('locale key parity', () => {
  it('en.json exists and is non-empty', () => {
    expect(baseKeys.length).toBeGreaterThan(0)
  })

  for (const [file, keys] of Object.entries(locales)) {
    if (file === 'en.json') continue
    it(`${file} has no keys missing vs en.json`, () => {
      const missing = baseKeys.filter(k => !keys.includes(k))
      expect(missing, `Missing in ${file}: ${missing.join(', ')}`).toHaveLength(0)
    })
    it(`${file} has no extra keys vs en.json`, () => {
      const extra = keys.filter(k => !baseKeys.includes(k))
      expect(extra, `Extra in ${file}: ${extra.join(', ')}`).toHaveLength(0)
    })
  }
})
```

4. Add test script to apps/desktop/package.json:
   "test:i18n": "vitest run src/renderer/src/locales/"

5. Run `pnpm --filter @agentkeeper/desktop test:i18n` — must pass.

6. Smoke-test the failure path: create a temporary apps/desktop/src/renderer/src/locales/fr.json as {} and confirm the test fails with a clear missing-keys message, then delete fr.json.
